                e.preventDefault();
                
                // \u5982\u679C\u94FE\u63A5\u6709onclick\u5904\u7406\u51FD\u6570\uFF0C\u624B\u52A8\u89E6\u53D1\u5B83
                if (typeof target.onclick === 'function') {
                  target.onclick.call(target);
                }
